// The standard parts table: published sizes of common parts and products (bearings, stepper motor faces, screw
// clearance holes, boards, spools), each value with its unit and the page it was read from. Generated by
// scripts/build-parts.ts from a folder of checked category files; this module only reads and validates it.
import { z } from 'zod'

/** A number, a designation, a formula, a list of numbers or points, or null when the source does not give it. */
const Value = z.union([z.number(), z.string(), z.array(z.number()), z.array(z.array(z.number())), z.array(z.string()), z.null()])

export const PartSizeSchema = z.object({
  /** Dotted path within the record, such as "bore", "ports.USB-C power.centerline" or "dimensions.finger_gap". */
  key: z.string().min(1),
  value: Value,
  unit: z.string().nullable(),
  /** The page or document the value was read from; null only when no document was found at all. */
  source_url: z.string().nullable(),
  /** maximum, minimum, typical or nominal, where the drawing says. */
  limit: z.string().optional(),
  /** derived: worked out from other published values (see derivation). unsourced: no published value (value is null). */
  status: z.enum(['derived', 'unsourced']).optional(),
  derivation: z.string().optional(),
  reason: z.string().optional(),
  /** Where in the source the value is: a page, table or figure. */
  locator: z.string().optional(),
  /** When the value was last read again in its source (UTC). */
  verified_utc: z.string().optional(),
  note: z.string().optional(),
})
export type PartSize = z.infer<typeof PartSizeSchema>

export const PartRecordSchema = z.object({
  category: z.string().min(1),
  id: z.string().min(1),
  name: z.string().min(1),
  /** Other names a request may use ("608ZZ", "NEMA 17", "Pi 4"). */
  aliases: z.array(z.string()),
  /** Text facts about the record that are not sizes: manufacturer, locator, coordinate system, notes. */
  info: z.record(z.string(), z.string()),
  sizes: z.array(PartSizeSchema),
})
export type PartRecord = z.infer<typeof PartRecordSchema>

export const PartCategorySchema = z.object({
  id: z.string().min(1),
  /** Words that name the category in a request ("bearing", "stepper", "spool"). */
  words: z.array(z.string()),
  /** What the category's values do and do not cover. */
  scope: z.string(),
  checked_utc: z.string(),
})
export type PartCategory = z.infer<typeof PartCategorySchema>

export const PartsTableSchema = z.object({
  schema_version: z.literal(1),
  /** How the values are licensed and attributed. */
  license: z.string(),
  categories: z.array(PartCategorySchema),
  records: z.array(PartRecordSchema),
})
export type PartsTable = z.infer<typeof PartsTableSchema>

/** Reads a parts table, refusing one that does not match the schema, has duplicate ids, or a record of no category. */
export function loadPartsTable(json: unknown): PartsTable {
  const table = PartsTableSchema.parse(json)
  const cats = new Set(table.categories.map((c) => c.id))
  const seen = new Set<string>()
  for (const r of table.records) {
    if (!cats.has(r.category)) throw new Error(`Parts table record ${r.id} names unknown category ${r.category}`)
    const k = `${r.category}/${r.id}`
    if (seen.has(k)) throw new Error(`Parts table has ${k} twice`)
    seen.add(k)
    for (const s of r.sizes) {
      if (s.status === 'unsourced' && s.value !== null) throw new Error(`Parts table ${k} ${s.key} is unsourced but has a value`)
      if (s.status !== 'unsourced' && s.value !== null && !s.source_url) throw new Error(`Parts table ${k} ${s.key} has a value without its source`)
    }
  }
  return table
}

let bundled: Promise<PartsTable> | undefined

/** The table that ships with the app, loaded on first use so it stays out of the first bundle. */
export function bundledPartsTable(): Promise<PartsTable> {
  bundled ??= import('./generated/standard-parts.json', { with: { type: 'json' } }).then((m) => loadPartsTable(m.default))
  return bundled
}
